name: Run tests on label

on:
  pull_request:
    types: [labeled]

permissions:
  contents: read
  pull-requests: read
  actions: read

jobs:
  run-tests:
    if: github.event.label.name == 'run-tests'
    runs-on: ubuntu-latest
    steps:
      - name: Determine if tests should run
        id: determine
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const actor = context.actor;
            const org = context.repo.owner;
            const isExternal = pr.user.type === 'User';
            // Check if the actor who added the label is a member of the org
            const res = await github.request('GET /orgs/{org}/members/{username}', {
              org,
              username: actor
            });
            const isMaintainer = res.status === 204;
            if (!isExternal || !isMaintainer) {
              core.setOutput('run', 'false');
              return;
            }
            core.setOutput('run', 'true');

      - name: Checkout repository
        if: steps.determine.outputs.run == 'true'
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name

